fn discover_pub_mod_name(line: &str) -> Option<String> {
    let trimmed = line.trim();
    let rest = trimmed.strip_prefix("pub mod ")?;
    let name = rest.strip_suffix(';')?.trim();
    if name.is_empty() {
        return None;
    }
    Some(module_name_to_plugin_name(name))
}

