//! op-web: Unified Web Server for op-dbus-v2
//!
//! This crate consolidates ALL HTTP services into a single server:
//! - REST API for tools, agents, chat, status
//! - WebSocket for real-time chat
//! - MCP protocol endpoint for Claude Desktop
//! - SSE for streaming events
//! - Static file serving for web UI
//!
//! ## Architecture
//!
//! ```text
//! ┌─────────────────────────────────────────────────────────────────┐
//! │                      op-web Server (:8080)                       │
//! ├─────────────────────────────────────────────────────────────────┤
//! │  /api/health     - Health check                                 │
//! │  /api/status     - System status                                │
//! │  /api/tools      - Tool registry                                │
//! │  /api/agents     - Agent management                             │
//! │  /api/chat       - Chat API                                     │
//! │  /api/events     - SSE event stream                             │
//! │  /mcp            - MCP JSON-RPC endpoint                        │
//! │  /ws             - WebSocket chat                               │
//! │  /               - Static files (WASM frontend)                 │
//! └─────────────────────────────────────────────────────────────────┘
//! ```

pub mod chat_store;
pub mod email;
pub mod groups_admin;
pub mod handlers;
pub mod mcp;
pub mod mcp_agents;
pub mod mcp_compact;
pub mod mcp_discovery;
pub mod middleware;
pub mod orchestrator;
pub mod privacy_container;
pub mod privacy_network;
pub mod privacy_openflow;
pub mod privacy_routes;
pub mod projection_client;
pub mod routes;
pub mod sse;
pub mod state;
pub mod state_manager_client;
pub mod users;
pub mod websocket;
pub mod wireguard;
pub mod zeroclaw_routes;

pub use orchestrator::UnifiedOrchestrator;
pub use state::AppState;

/// Server configuration
#[derive(Debug, Clone)]
pub struct ServerConfig {
    pub host: String,
    pub port: u16,
    pub static_dir: Option<String>,
    pub enable_cors: bool,
    pub enable_compression: bool,
}

impl Default for ServerConfig {
    fn default() -> Self {
        Self {
            host: "0.0.0.0".to_string(),
            port: 8080,
            static_dir: Some("static".to_string()),
            enable_cors: true,
            enable_compression: true,
        }
    }
}

//! API routes and route handlers

use axum::{
    extract::Extension,
    routing::{delete, get, post},
    Router,
};
use std::sync::Arc;
use tower_http::compression::CompressionLayer;
use tower_http::cors::{Any, CorsLayer};
use tower_http::trace::TraceLayer;

use crate::groups_admin;
use crate::handlers;
use crate::mcp;
use crate::mcp_agents;
use crate::mcp_discovery;
use crate::middleware::security;
use crate::sse;
use crate::state::AppState;
use crate::websocket;

pub mod admin;
#[allow(dead_code)]
pub mod chat;
#[allow(dead_code)]
pub mod llm;

/// Create the complete router with all routes
pub fn create_router(state: Arc<AppState>) -> Router {
    // CORS configuration
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    // API routes
    let api_routes = Router::new()
        // Health & Status
        .route("/health", get(handlers::health::health_handler))
        .route("/status", get(handlers::status::status_handler))
        // Schema — single source of truth from shared memory
        .route("/schema", get(handlers::schema::schema_handler))
        // Identity sled — live WireGuard identity from shared memory
        .route(
            "/identity/sled",
            get(handlers::identity::identity_sled_handler),
        )
        // Dashboard
        .route(
            "/dashboard/metrics",
            get(handlers::dashboard::dashboard_metrics_handler),
        )
        .route(
            "/dashboard/projections",
            get(handlers::dashboard::dashboard_projections_handler),
        )
        // Users
        .route("/users", get(handlers::users::list_users_handler))
        .route("/users/:id", get(handlers::users::get_user_handler))
        // VPN
        .route("/vpn/status", get(handlers::vpn::vpn_status_handler))
        .route(
            "/vpn/connections",
            get(handlers::vpn::vpn_connections_handler),
        )
        .route("/vpn/config", get(handlers::vpn::vpn_config_handler))
        // Mail
        .route("/mail/status", get(handlers::mail::mail_status_handler))
        .route("/mail/queue", get(handlers::mail::mail_queue_handler))
        .route("/mail/accounts", get(handlers::mail::mail_accounts_handler))
        // Logs
        .route("/logs", get(handlers::logs::logs_handler))
        .route("/logs/stream", get(handlers::logs::logs_stream_handler))
        // Chat endpoints
        .route("/chat", post(handlers::chat::chat_handler))
        .route("/chat/stream", post(handlers::chat::chat_stream_handler))
        .route(
            "/zeroclaw/chat",
            post(handlers::zeroclaw::zeroclaw_chat_handler),
        )
        .route(
            "/zeroclaw/chat/stream",
            post(handlers::zeroclaw::zeroclaw_chat_stream_handler),
        )
        .route(
            "/zeroclaw/schema",
            get(handlers::zeroclaw::zeroclaw_schema_handler),
        )
        .route("/chat/sessions", get(handlers::chat::list_sessions_handler))
        .route(
            "/chat/sessions",
            post(handlers::chat::create_session_handler),
        )
        .route(
            "/chat/sessions/:id",
            delete(handlers::chat::delete_session_handler),
        )
        .route("/chat/message", post(handlers::chat::send_message_handler))
        .route(
            "/chat/history/:session_id",
            get(handlers::chat::get_history_handler),
        )
        .route(
            "/chat/transcript",
            post(handlers::chat::save_transcript_handler),
        )
        .route(
            "/chat/system-prompt",
            get(handlers::chat::get_system_prompt_handler),
        )
        .route(
            "/chat/system-prompt",
            axum::routing::put(handlers::chat::update_system_prompt_handler),
        )
        // Analytics / Accountability
        .route(
            "/analytics/semantic-search",
            get(handlers::analytics::semantic_search_handler),
        )
        // Tool endpoints
        .route("/tools", get(handlers::tools::list_tools_handler))
        .route("/tools/:name", get(handlers::tools::get_tool_handler))
        .route("/tool", post(handlers::tools::execute_tool_handler))
        .route(
            "/tools/:name/execute",
            post(handlers::tools::execute_named_tool_handler),
        )
        // Agent endpoints
        .route("/agents", get(handlers::agents::list_agents_handler))
        .route("/agents", post(handlers::agents::spawn_agent_handler))
        .route(
            "/agents/types",
            get(handlers::agents::list_agent_types_handler),
        )
        .route("/agents/:id", get(handlers::agents::get_agent_handler))
        .route(
            "/agents/:id",
            axum::routing::delete(handlers::agents::kill_agent_handler),
        )
        // LLM endpoints
        .route("/llm/status", get(handlers::llm::llm_status_handler))
        .route("/llm/providers", get(handlers::llm::list_providers_handler))
        .route("/llm/models", get(llm::get_models))
        .route(
            "/llm/models/:provider",
            get(handlers::llm::list_models_for_provider_handler),
        )
        .route("/llm/chat", post(handlers::chat::send_message_handler))
        // OpenClaw endpoints (internal/base layer)
        .route(
            "/openclaw/status",
            get(handlers::openclaw::openclaw_status_handler),
        )
        .route(
            "/openclaw/config",
            get(handlers::openclaw::openclaw_config_handler),
        )
        .route(
            "/openclaw/chat",
            post(handlers::openclaw::openclaw_chat_handler),
        )
        .route(
            "/openclaw/models",
            get(handlers::openclaw::openclaw_models_handler),
        )
        // Assistant endpoints (user-facing aliases — same handlers, branded URLs)
        .route(
            "/assistant/status",
            get(handlers::openclaw::openclaw_status_handler),
        )
        .route(
            "/assistant/config",
            get(handlers::openclaw::openclaw_config_handler),
        )
        .route(
            "/assistant/chat",
            post(handlers::openclaw::openclaw_chat_handler),
        )
        .route(
            "/assistant/models",
            get(handlers::openclaw::openclaw_models_handler),
        )
        // MCP server management endpoints
        .route("/mcp/servers", get(handlers::mcp::list_servers_handler))
        .route("/mcp/servers/:id", get(handlers::mcp::get_server_handler))
        .route(
            "/mcp/cognitive/agents",
            get(handlers::mcp::list_agents_handler),
        )
        .route(
            "/mcp/cognitive/agents",
            post(handlers::mcp::set_agents_handler),
        )
        .route(
            "/mcp/cognitive/memory",
            post(handlers::mcp::query_memory_handler),
        )
        .route(
            "/mcp/cognitive/memory/:key",
            delete(handlers::mcp::delete_memory_handler),
        )
        .route(
            "/mcp/cognitive/memory/stats",
            get(handlers::mcp::memory_stats_handler),
        )
        // MCP discovery endpoints
        .route("/mcp/_config", get(mcp::config_handler))
        // SSE events
        .route("/events", get(sse::sse_handler))
        // Privacy router endpoints
        .route("/privacy/signup", post(handlers::privacy::signup))
        .route("/privacy/verify", get(handlers::privacy::verify))
        .route(
            "/privacy/config/:user_id",
            get(handlers::privacy::get_config),
        )
        .route("/privacy/status", get(handlers::privacy::status))
        .route(
            "/privacy/credentials",
            post(handlers::privacy::set_credentials),
        )
        // Google OAuth endpoints
        .route("/privacy/google/auth", get(handlers::privacy::google_auth))
        .route(
            "/privacy/google/callback",
            get(handlers::privacy::google_callback),
        );

    // MCP JSON-RPC endpoints (profile-based and legacy)
    let mcp_route = mcp::create_mcp_router();

    // Critical Agents MCP endpoint (SSE-based, direct tool access)
    // These are added separately to avoid state conflicts
    let agents_mcp_route = Router::new()
        .route(
            "/mcp/agents",
            get(mcp_agents::mcp_agents_sse_handler_stateless),
        )
        .route(
            "/mcp/agents/message",
            post(mcp_agents::mcp_agents_message_handler_stateless),
        );

    // WebSocket route
    let ws_route = Router::new().route("/ws", get(websocket::websocket_handler));

    // Main router - agents_mcp_route FIRST so it takes precedence
    let router = Router::new()
        .nest("/api", api_routes)
        // Human-facing privacy verification flow (magic-link target)
        .route("/privacy/verify", get(handlers::privacy::verify_redirect))
        .route(
            "/privacy/access",
            get(handlers::privacy::privacy_access_message),
        )
        // JSON-RPC compatibility aliases (mirror /mcp)
        .route("/jsonrpc", post(mcp::jsonrpc_handler))
        .route("/rpc", post(mcp::jsonrpc_handler))
        .merge(agents_mcp_route) // Agents first (more specific)
        .nest("/mcp", mcp_route) // Nest MCP routes under /mcp (not root)
        .merge(ws_route)
        // Well-known discovery endpoint for auto-configuration
        .route(
            "/.well-known/mcp.json",
            get(mcp_discovery::mcp_discovery_handler),
        )
        .nest("/groups-admin", groups_admin::create_groups_admin_router())
        .nest("/admin", admin::admin_routes());

    // No SPA fallback: op-web is API/gRPC only. The native zeroclaw-gui client
    // consumes state over gRPC-Web + reflection; unmatched routes return 404.
    router
        .layer(Extension(state))
        .layer(axum::middleware::from_fn(security::ip_security_middleware))
        .layer(cors)
        .layer(CompressionLayer::new())
        .layer(TraceLayer::new_for_http())
}

//! Router configuration for op-web

use axum::{
    routing::{get, post},
    Router,
};
use std::sync::Arc;

use crate::routes;
use crate::state::AppState;
use crate::websocket::handle_websocket;

/// Web service router builder
pub struct WebServiceRouter;

impl WebServiceRouter {
    /// Create a new router with all routes
    pub fn new() -> Self {
        Self
    }
}

/// Create the main application router
pub fn create_router(state: Arc<AppState>, static_dir: Option<String>) -> Router {
    let router = Router::new()
        // Health check
        .route("/api/health", get(routes::health_check))
        // LLM routes
        .route("/api/schema/catalog", get(crate::handlers::schema::schema_catalog_raw_handler))
        .route("/api/schema/catalog/detail", get(crate::handlers::schema::schema_catalog_handler))
        .route("/api/llm/status", get(routes::llm::get_llm_status))
        .route(
            "/api/llm/providers",
            get(crate::handlers::llm::list_providers_handler),
        )
        .route("/api/llm/models", get(routes::llm::get_models))
        // Chat routes
        .route("/api/chat", post(routes::chat::chat_message))
        // Tool routes
        .route("/api/tools", get(routes::tools::list_tools))
        .route("/api/tools/:name", get(routes::tools::get_tool))
        .route(
            "/api/tools/:name/execute",
            post(routes::tools::execute_tool),
        )
        // WebSocket
        .route("/ws", get(handle_websocket))
        .with_state(state);

    // No SPA fallback: API/WebSocket only. Unmatched routes return 404.
    let _ = static_dir;
    router
}

/// Create WebSocket-only router (for composition)
pub fn create_websocket_router(state: Arc<AppState>) -> Router {
    Router::new()
        .route("/ws", get(handle_websocket))
        .with_state(state)
}

//! Web server implementation

use axum::{routing::get, Router};
use std::net::SocketAddr;
use std::path::PathBuf;
use tower::ServiceBuilder;
use tower_governor::{governor::GovernorConfigBuilder, GovernorLayer};
use tower_http::{
    compression::CompressionLayer,
    cors::{Any, CorsLayer},
    services::ServeDir,
    trace::TraceLayer,
};
use tracing::info;

use crate::routes::api_router;
use crate::state::AppState;
use crate::websocket::ws_handler;

// Re-export for main.rs
pub use crate::websocket::ws_handler as websocket_handler;

/// Web server configuration
#[derive(Debug, Clone)]
pub struct WebServerConfig {
    /// Address to bind to
    pub addr: SocketAddr,
    /// Path to static files (optional)
    pub static_dir: Option<PathBuf>,
    /// Enable CORS
    pub cors_enabled: bool,
    /// Rate limiting configuration
    pub rate_limit: RateLimitConfig,
}

/// Rate limiting configuration
#[derive(Debug, Clone)]
pub struct RateLimitConfig {
    /// Requests per minute per IP
    pub requests_per_minute: u64,
    /// Burst size (additional requests allowed)
    pub burst_size: u64,
    /// Enable rate limiting
    pub enabled: bool,
}

impl Default for RateLimitConfig {
    fn default() -> Self {
        Self {
            requests_per_minute: 100, // Matches Caddy config
            burst_size: 20,
            enabled: true,
        }
    }
}

impl Default for WebServerConfig {
    fn default() -> Self {
        Self {
            addr: SocketAddr::from(([127, 0, 0, 1], 3000)),
            static_dir: None,
            cors_enabled: true,
            rate_limit: Default::default(),
        }
    }
}

impl WebServerConfig {
    pub fn new(addr: SocketAddr) -> Self {
        Self {
            addr,
            ..Default::default()
        }
    }

    pub fn with_static_dir(mut self, path: impl Into<PathBuf>) -> Self {
        self.static_dir = Some(path.into());
        self
    }
}

/// Web server
pub struct WebServer {
    config: WebServerConfig,
    state: AppState,
}

impl WebServer {
    /// Create a new web server
    pub fn new(config: WebServerConfig, state: AppState) -> Self {
        Self { config, state }
    }

    /// Build the router
    pub fn router(&self) -> Router {
        let mut app = Router::new()
            // API routes
            .nest("/api", api_router())
            // WebSocket endpoint for streaming
            .route("/ws", get(ws_handler))
            .with_state(self.state.clone());

        // Build middleware stack with consistent types
        let middleware = ServiceBuilder::new()
            .layer(TraceLayer::new_for_http())
            .layer(CompressionLayer::new()); // Automatic gzip/brotli compression

        let app = app.layer(middleware);

        // Add rate limiting if enabled (as separate layer)
        let app = if self.config.rate_limit.enabled {
            let rate_limit_per_sec = self.config.rate_limit.requests_per_minute / 60;
            info!(
                "Rate limiting enabled: {} requests/second, burst: {}",
                rate_limit_per_sec, self.config.rate_limit.burst_size
            );

            let governor_conf = GovernorConfigBuilder::default()
                .per_second(rate_limit_per_sec)
                .burst_size(self.config.rate_limit.burst_size as u32)
                .finish()
                .expect("rate limit configuration should be valid");

            app.layer(GovernorLayer {
                config: governor_conf.into(),
            })
        } else {
            app
        };

        // Add CORS if enabled (as separate layer)
        let app = if self.config.cors_enabled {
            let cors = CorsLayer::new()
                .allow_origin(Any)
                .allow_methods(Any)
                .allow_headers(Any);
            app.layer(cors)
        } else {
            app
        };

        app
    }

    /// Run the server
    pub async fn run(self) -> Result<(), std::io::Error> {
        let router = self.router();
        let listener = tokio::net::TcpListener::bind(self.config.addr).await?;

        info!("Web server listening on http://{}", self.config.addr);

        axum::serve(
            listener,
            router.into_make_service_with_connect_info::<SocketAddr>(),
        )
        .await
    }
}

    ) -> (
        Vec<crate::proto::registry::ComponentInfo>,
        tokio::sync::broadcast::Receiver<crate::proto::registry::RegistryEvent>,
    ) {
        let inner = self.registry.read().await;
        let snapshot: Vec<_> = inner.components.values().cloned().collect();
        let rx = inner.watch_tx.subscribe();
        (snapshot, rx)
    }
}

/// Run gRPC server for all Operation services.
///
/// Includes:
///   - StateSync, PluginService, EventChainService, OvsdbMirror, RuntimeMirror
///   - ComponentRegistry, MailService, PrivacyNetworkService, RegistrationService
///   - gRPC server reflection (all protos in combined descriptor)
///   - gRPC health protocol (liveness for deploy verification and load balancers)
///
/// Adding a new domain service:
///   1. Add the generated server import below
///   2. Add `.add_service(...)` to the builder chain
///   3. Mark it serving via health_reporter
pub async fn run_grpc_server(
    addr: std::net::SocketAddr,
    mutation_engine: Arc<MutationEngine>,
    plugin_provider: Option<Arc<dyn PluginSchemaProvider>>,
    tls_identity: Option<Identity>,
) -> Result<(), tonic::transport::Error> {
    use crate::proto::dbus_passthrough_server::DbusPassthroughServer;
    use crate::proto::event_chain_service_server::EventChainServiceServer;
    use crate::proto::mail::mail_service_server::MailServiceServer;
    use crate::proto::ovsdb_mirror_server::OvsdbMirrorServer;
    use crate::proto::plugin_service_server::PluginServiceServer;
    use crate::proto::privacy::privacy_network_service_server::PrivacyNetworkServiceServer;
    use crate::proto::registration::registration_service_server::RegistrationServiceServer;
    use crate::proto::registry::component_registry_server::ComponentRegistryServer;
    use crate::proto::runtime_mirror_server::RuntimeMirrorServer;
    use crate::proto::state_sync_server::StateSyncServer;
    use op_cache::grpc::{AgentServiceImpl, McpServiceImpl, OrchestratorServiceImpl};
    use op_cache::proto::mcp_service_server::McpServiceServer;

    // Build MCP service backed by agent registry.
    let agent_svc = std::sync::Arc::new(AgentServiceImpl::new());
    let cache_svc = std::sync::Arc::new(op_cache::grpc::CacheServiceImpl::with_ttl(3600));
    let orch_svc = std::sync::Arc::new(OrchestratorServiceImpl::with_config(
        agent_svc.clone(),
        cache_svc,
        2,    // workstack_threshold
        true, // enable_caching
        3,    // promotion_threshold
    ));
    let mcp_svc = std::sync::Arc::new(McpServiceImpl::new(agent_svc, orch_svc));

    let server = if let Some(provider) = plugin_provider {
        OperationGrpcServer::with_plugin_provider(mutation_engine, provider)
    } else {
        OperationGrpcServer::new(mutation_engine)
    };
    let server = match QdrantSemanticShuttle::new().await {
        Ok(shuttle) => server.with_semantic_shuttle(Arc::new(shuttle)),
        Err(error) => {
            warn!(%error, "semantic shuttle unavailable; SearchSemanticTrace will return failed_precondition");
            server
        }
    };

    // Reflection — exposes combined FileDescriptorSet covering all domain protos.
    // Enables grpcurl discovery and drives MCP tool auto-registration in op-chat.
    // chat.proto is compiled into the combined descriptor set so ChatService is
    // discoverable alongside StateSync, PluginService, etc.
    let reflection = tonic_reflection::server::Builder::configure()
        .register_encoded_file_descriptor_set(crate::proto::FILE_DESCRIPTOR_SET)
        .build_v1()
        .expect("failed to build reflection service");

    // Health — standard gRPC health protocol for deploy verification and LB probes.
    let (mut health_reporter, health_service) = tonic_health::server::health_reporter();
    health_reporter
        .set_serving::<StateSyncServer<OperationGrpcServer>>()
        .await;
    health_reporter
        .set_serving::<PluginServiceServer<OperationGrpcServer>>()
        .await;
    health_reporter
        .set_serving::<EventChainServiceServer<OperationGrpcServer>>()
        .await;
    health_reporter
        .set_serving::<OvsdbMirrorServer<OperationGrpcServer>>()
        .await;
    health_reporter
        .set_serving::<RuntimeMirrorServer<OperationGrpcServer>>()
        .await;
    health_reporter
        .set_serving::<ComponentRegistryServer<OperationGrpcServer>>()
        .await;
    health_reporter
        .set_serving::<MailServiceServer<OperationGrpcServer>>()
        .await;
    health_reporter
        .set_serving::<PrivacyNetworkServiceServer<OperationGrpcServer>>()
        .await;
    health_reporter
        .set_serving::<RegistrationServiceServer<OperationGrpcServer>>()
        .await;
    health_reporter
        .set_serving::<crate::proto::chat::chat_service_server::ChatServiceServer<crate::chat_service::ChatServiceImpl>>()
        .await;

    info!(addr = %addr, "gRPC bridge listening");

    // Wrap services with gRPC-Web support and allow JSON encoding.
    // The GhostbridgeInterceptor enforces the Absolute Base rule on every
    // inbound request before it reaches a service handler.
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    let mut builder = tonic::transport::Server::builder()
        .accept_http1(true)
        .layer(cors);

    if let Some(identity) = tls_identity {
        builder = builder.tls_config(ServerTlsConfig::new().identity(identity))?;
    }

    let server = builder
        .add_service(tonic_web::enable(StateSyncServer::with_interceptor(
            server.clone(),
            interceptor::ghostbridge_interceptor,
        )))
        .add_service(tonic_web::enable(PluginServiceServer::with_interceptor(
            server.clone(),
            interceptor::ghostbridge_interceptor,
        )))
        .add_service(tonic_web::enable(
            EventChainServiceServer::with_interceptor(
                server.clone(),
                interceptor::ghostbridge_interceptor,
            ),
        ))
        .add_service(tonic_web::enable(OvsdbMirrorServer::with_interceptor(
            server.clone(),
            interceptor::ghostbridge_interceptor,
        )))
        .add_service(tonic_web::enable(RuntimeMirrorServer::with_interceptor(
            server.clone(),
            interceptor::ghostbridge_interceptor,
        )))
        .add_service(tonic_web::enable(
            ComponentRegistryServer::with_interceptor(
                server.clone(),
                interceptor::ghostbridge_interceptor,
            ),
        ))
        .add_service(tonic_web::enable(MailServiceServer::with_interceptor(
            server.clone(),
            interceptor::ghostbridge_interceptor,
        )))
        .add_service(tonic_web::enable(
            PrivacyNetworkServiceServer::with_interceptor(
                server.clone(),
                interceptor::ghostbridge_interceptor,
            ),
        ))
        .add_service(tonic_web::enable(
            RegistrationServiceServer::with_interceptor(
                server.clone(),
                interceptor::ghostbridge_interceptor,
            ),
        ))
        .add_service(tonic_web::enable(DbusPassthroughServer::with_interceptor(
            server.clone(),
            interceptor::ghostbridge_interceptor,
        )))
        .add_service(tonic_web::enable(tonic::codegen::InterceptedService::new(
            McpServiceServer::from_arc(mcp_svc),
            interceptor::ghostbridge_interceptor,
        )))
        .add_service(tonic_web::enable(
            crate::proto::chat::chat_service_server::ChatServiceServer::new(
                crate::chat_service::ChatServiceImpl::new(),
            ),
        ))
        .add_service(tonic_web::enable(reflection))
        .add_service(tonic_web::enable(health_service));

    server.serve(addr).await
}

