178	/// Run the zeroclaw Axum host.
179	///
180	/// Returns only when both listeners exit (which should not happen under normal
181	/// operation).
182	pub async fn run_zeroclaw_server(config: ServerConfig) -> anyhow::Result<()> {
183	    let loader = Arc::new(SchemaLoader::new(&config.schema_path)?);
184	
185	    // Channel for D-Bus-triggered rebind requests. Only `SchemaPath` changes are
186	    // applied live; `BindAddr` changes are recorded and honored on the next
187	    // restart.
188	    let (rebind_tx, mut rebind_rx) = mpsc::channel::<String>(4);
189	
190	    // D-Bus object for runtime configuration.
191	    let dbus_object = ZeroclawAxumHostObject::new(loader.clone(), rebind_tx)?;
192	    let _dbus_connection = register_zeroclaw_host_object(dbus_object).await?;
193	
194	    // SIGHUP reload watcher.
195	    let _sighup_handle = loader.clone().watch_sighup();
196	
197	    // PluginService (PluginService.CallMethod) backed by the authoritative
198	    // MutationEngine. This is how createunixsocket is invoked: a CallMethod with
199	    // plugin_id="unix_socket" routes through MutationEngine.mutate →
200	    // UnixSocketPlugin::create_unix_socket. The sled identity is resolved as
201	    // the actor_id inside mutate when the caller omits it.
202	    let event_chain = Arc::new(tokio::sync::RwLock::new(
203	        op_state_store::EventChain::new(op_state_store::ChainConfig::default()),
204	    ));
205	    let ovsdb = Arc::new(op_network::rovs_proxy::OvsdbDbusClient::new());
206	    let nonnet = Arc::new(op_jsonrpc::nonnet::NonNetDb::new());
207	    let mutation_engine = Arc::new(MutationEngine::new(event_chain, ovsdb, nonnet));
208	    let operation_server = OperationGrpcServer::new(mutation_engine);
209	    let plugin_service = PluginServiceServer::with_interceptor(
210	        operation_server,
211	        crate::interceptor::GhostbridgeInterceptor,
212	    );
213	
214	    // Unix socket listener for native gRPC.
215	    let unix_socket = config.unix_socket.clone();
216	    if let Some(parent) = unix_socket.parent() {
217	        let _ = std::fs::create_dir_all(parent);
218	    }
219	    let _ = std::fs::remove_file(&unix_socket);
220	    let unix_listener = tokio::net::UnixListener::bind(&unix_socket)?;
221	    info!(path = %unix_socket.display(), "zeroclaw native gRPC listening on Unix socket");
222	
223	    let unix_incoming = tokio_stream::wrappers::UnixListenerStream::new(unix_listener);
224	
225	    let tonic_server = tonic::transport::Server::builder()
226	        .add_routes(build_tonic_routes(loader.clone(), plugin_service.clone()))
227	        .serve_with_incoming(unix_incoming);
228	
229	    // TCP listener for HTTP + gRPC-Web.
230	    let bind_addr: SocketAddr = config.bind_addr.parse()?;
231	    let tcp_listener = tokio::net::TcpListener::bind(bind_addr).await?;
232	    info!(addr = %bind_addr, "zeroclaw HTTP/gRPC-Web listening on TCP");
233	
234	    let axum_app = build_axum_app(loader.clone(), plugin_service);
235	    let tcp_server = axum::serve(tcp_listener, axum_app);
236	
237	    // Rebind task: when a new bind address is requested, restart the TCP server.
238	    // The current implementation starts the initial TCP server; subsequent
239	    // rebinds require a restart to keep the listener lifecycle simple and safe.
240	    let rebind_task = tokio::spawn(async move {
241	        while let Some(new_bind) = rebind_rx.recv().await {
242	            info!(new_bind = %new_bind, "D-Bus rebind request received; will be honored on next restart");
243	        }
244	    });
245	
246	    let (unix_result, tcp_result) = tokio::join!(tonic_server, tcp_server);
247	    let _ = rebind_task.await;
248	    unix_result.map_err(|e| anyhow::anyhow!("Unix server error: {}", e))?;
249	    tcp_result.map_err(|e| anyhow::anyhow!("TCP server error: {}", e))
250	}
