/// Assemble the complete gRPC service set for the zeroclaw bridge.
///
/// This is the SINGLE place the bridge's service surface is defined, so the
/// native-gRPC (Unix socket) and gRPC-Web (TCP) listeners expose exactly the
/// same services. Includes:
///   - ZeroclawService — plugin-owned schema get/watch
///   - PluginService   — MutationEngine-backed CallMethod (createunixsocket, …)
///   - ChatService     — operator chat stream (delegator, forced tool calling)
///   - gRPC reflection — combined FileDescriptorSet so the assistant container's
///     zeroclaw-gui discovers every service from this one endpoint
fn build_routes(
    loader: Arc<SchemaLoader>,
    plugin_service: PluginSvcIntercepted,
) -> tonic::service::Routes {
    let service = ZeroclawGrpcService { loader };
    let zeroclaw_svc = tonic_web::enable(ZeroclawServiceServer::new(service));
    let plugin_svc = tonic_web::enable(plugin_service);
    let chat_svc = tonic_web::enable(ChatServiceServer::new(ChatServiceImpl::new()));

    // Reflection exposes the combined descriptor set covering every domain proto
    // (including chat.proto), so grpcurl/zeroclaw-gui can `list` and resolve
    // method schemas over this single endpoint.
    let reflection = tonic_web::enable(
        tonic_reflection::server::Builder::configure()
            .register_encoded_file_descriptor_set(crate::proto::FILE_DESCRIPTOR_SET)
            .build_v1()
            .expect("failed to build reflection service"),
    );

    tonic::service::Routes::new(zeroclaw_svc)
        .add_service(plugin_svc)
        .add_service(chat_svc)
        .add_service(reflection)
}

/// Build the axum `Router` that serves the gRPC service over HTTP/gRPC-Web.
pub fn build_axum_app(loader: Arc<SchemaLoader>, plugin_service: PluginSvcIntercepted) -> Router {
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    build_routes(loader, plugin_service)
        .into_axum_router()
        .layer(cors)
        .layer(GhostbridgeTraceLayer::new())
}

/// Build the tonic `Routes` used for the native-gRPC Unix socket side.
fn build_tonic_routes(
    loader: Arc<SchemaLoader>,
    plugin_service: PluginSvcIntercepted,
) -> tonic::service::Routes {
    build_routes(loader, plugin_service)
}

