1	//! `blockchain` StatePlugin — exposes the live streaming-blockchain audit chain
2	//! (`op-blockchain`) through the `org.dbus.v1.plugins` surface, reachable over
3	//! `PluginService.CallMethod`.
4	//!
5	//! This is the correct home for the capability the Lovable frontend mistakenly
6	//! called as a standalone `operation.blockchain.v1.BlockchainService` gRPC
7	//! package — there is no such proto and there must not be one. New backend
8	//! capabilities register here as plugins; the served gRPC surface stays the one
9	//! shared route-builder.
10	//!
11	//! Every read is live: [`query_current_state`](BlockchainPlugin::query_current_state)
12	//! opens the on-disk chain at `$OPDBUS_BLOCKCHAIN_PATH` and reports its real
13	//! snapshots, DR `current_state`, snapshot interval and retention policy.
14	//! [`create_checkpoint`](BlockchainPlugin::create_checkpoint) performs a real
15	//! `create_snapshot()` and `apply_state` writes the DR state through the chain.
16	//! Nothing here is mocked.
17	
18	use super::plugin_schema_defs::schema_from_state;
19	use anyhow::Result;
20	use async_trait::async_trait;
21	use op_blockchain::StreamingBlockchain;
22	use op_state::{
23	    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
24	};
25	use op_state_store::PluginSchema;
26	use serde::{Deserialize, Serialize};
27	use simd_json::prelude::ValueAsContainer;
28	use simd_json::{json, OwnedValue as Value};
29	use std::path::PathBuf;
30	
31	/// Default on-disk location of the streaming blockchain when
32	/// `$OPDBUS_BLOCKCHAIN_PATH` is unset.
33	const DEFAULT_BASE_PATH: &str = "/var/lib/opdbus/blockchain";
34	
35	/// Key under which the disaster-recovery "current state" blob is persisted in
36	/// the state subvolume (`StreamingBlockchain::write_current_state` writes here).
37	const CURRENT_STATE_KEY: &str = "current";
38	
39	#[derive(Debug, Clone, Serialize, Deserialize)]
40	pub struct RetentionView {
41	    pub hourly: usize,
42	    pub daily: usize,
43	    pub weekly: usize,
44	    pub quarterly: usize,
45	}
46	
47	#[derive(Debug, Clone, Serialize, Deserialize)]
48	pub struct SnapshotEntry {
49	    pub name: String,
50	    pub created: String,
51	}
52	
53	#[derive(Debug, Clone, Serialize, Deserialize)]
54	pub struct BlockchainState {
55	    /// `active` once the chain exists on disk, `uninitialized` before first write.
56	    pub status: String,
57	    pub base_path: String,
58	    pub snapshot_interval: String,
59	    pub retention: RetentionView,
60	    pub snapshot_count: usize,
61	    pub snapshots: Vec<SnapshotEntry>,
62	    pub current_state: Value,
63	}
64	
65	pub struct BlockchainPlugin {
66	    base_path: PathBuf,
67	}
68	
69	impl Default for BlockchainPlugin {
70	    fn default() -> Self {
71	        Self::new()
72	    }
73	}
74	
75	impl BlockchainPlugin {
76	    pub fn new() -> Self {
77	        let base_path = std::env::var("OPDBUS_BLOCKCHAIN_PATH")
78	            .map(PathBuf::from)
79	            .unwrap_or_else(|_| PathBuf::from(DEFAULT_BASE_PATH));
80	        Self { base_path }
81	    }
82	
83	    /// Open the on-disk chain. `StreamingBlockchain::new` is idempotent: it only
84	    /// (re)creates subvolumes that do not already exist, so opening an existing
85	    /// chain is non-destructive. Callers that must not create the chain should
86	    /// gate on `base_path.exists()` first (see [`read_live`]).
87	    async fn open(&self) -> Result<StreamingBlockchain> {
88	        StreamingBlockchain::new(&self.base_path).await
89	    }
90	
91	    /// Read the live chain state. If the chain has not been initialized on disk
92	    /// yet, report an honest `uninitialized` state rather than creating it as a
93	    /// side effect of a read.
94	    async fn read_live(&self) -> Result<BlockchainState> {
95	        if !self.base_path.exists() {
96	            return Ok(BlockchainState {
97	                status: "uninitialized".to_string(),
98	                base_path: self.base_path.display().to_string(),
99	                snapshot_interval: String::new(),
100	                retention: RetentionView {
101	                    hourly: 0,
102	                    daily: 0,
103	                    weekly: 0,
104	                    quarterly: 0,
105	                },
106	                snapshot_count: 0,
107	                snapshots: Vec::new(),
108	                current_state: json!({}),
109	            });
110	        }
111	
112	        let chain = self.open().await?;
113	
114	        let snapshots: Vec<SnapshotEntry> = chain
115	            .list_snapshots()
116	            .await
117	            .unwrap_or_default()
118	            .into_iter()
119	            .map(|(name, created)| SnapshotEntry { name, created })
120	            .collect();
121	
122	        let current_state = chain
123	            .read_state(CURRENT_STATE_KEY)
124	            .await
125	            .unwrap_or_else(|_| json!({}));
126	
127	        let retention = chain.retention_policy();
128	
129	        Ok(BlockchainState {
130	            status: "active".to_string(),
131	            base_path: chain.base_path().display().to_string(),
132	            snapshot_interval: chain.snapshot_interval().to_string(),
133	            retention: RetentionView {
134	                hourly: retention.hourly,
135	                daily: retention.daily,
136	                weekly: retention.weekly,
137	                quarterly: retention.quarterly,
138	            },
139	            snapshot_count: snapshots.len(),
140	            snapshots,
141	            current_state,
142	        })
143	    }
144	
145	    /// Synchronous shape exemplar used only to derive the [`PluginSchema`]. The
146	    /// schema describes the *shape* of `query_current_state`'s output (field
147	    /// names + types); the data path itself is always live.
148	    fn schema_exemplar() -> BlockchainState {
149	        BlockchainState {
150	            status: "active".to_string(),
151	            base_path: DEFAULT_BASE_PATH.to_string(),
152	            snapshot_interval: "every-15-minutes".to_string(),
153	            retention: RetentionView {
154	                hourly: 24,
155	                daily: 7,
156	                weekly: 4,
157	                quarterly: 4,
158	            },
159	            snapshot_count: 0,
160	            snapshots: vec![SnapshotEntry {
161	                name: "state-000001".to_string(),
162	                created: "1970-01-01 00:00:00 UTC".to_string(),
163	            }],
164	            current_state: json!({}),
165	        }
166	    }
167	}
168	
169	#[async_trait]
170	impl StatePlugin for BlockchainPlugin {
171	    fn name(&self) -> &str {
172	        "blockchain"
173	    }
174	
175	    fn version(&self) -> &str {
176	        "1.0.0"
177	    }
178	
179	    fn schema(&self) -> Option<PluginSchema> {
180	        Some(blockchain_schema())
181	    }
182	
183	    async fn query_current_state(&self) -> Result<Value> {
184	        Ok(simd_json::serde::to_owned_value(self.read_live().await?)?)
185	    }
186	
187	    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
188	        // The only writable projection of an append-only audit chain is its DR
189	        // `current_state` blob. Emit a real Modify when the desired state
190	        // differs, otherwise a NoOp.
191	        let actions = if current == desired {
192	            vec![StateAction::NoOp {
193	                resource: "current_state".to_string(),
194	            }]
195	        } else {
196	            vec![StateAction::Modify {
197	                resource: "current_state".to_string(),
198	                changes: desired.clone(),
199	            }]
200	        };
201	        Ok(StateDiff {
202	            plugin: self.name().to_string(),
203	            actions,
204	            metadata: DiffMetadata {
205	                timestamp: chrono::Utc::now().timestamp(),
206	                current_hash: String::new(),
207	                desired_hash: String::new(),
208	            },
209	        })
210	    }
211	
212	    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {

