use std::collections::HashMap;

const DEFAULT_VOYAGE_MODEL: &str = "voyage-4-lite";
const DEFAULT_COLLECTION: &str = "ctl_plane_reasoning_episodes";
const DEFAULT_VECTOR_DIMS: u32 = 1024;
const DEFAULT_DEDUP_WINDOW_HRS: u32 = 24;
