    fn default() -> Self {
        Self {
            voyage_model: default_voyage_model(),
            qdrant_collection: default_collection(),
            vector_dims: DEFAULT_VECTOR_DIMS,
            dedup_window_hrs: DEFAULT_DEDUP_WINDOW_HRS,
