            .path(req.path.as_str())
            .map_err(|e| Status::invalid_argument(e.to_string()))?
            .build()
            .await
            .map_err(|e| Status::internal(e.to_string()))?;

        let iface = zbus::names::InterfaceName::try_from(req.interface.as_str())
            .map_err(|e| Status::invalid_argument(e.to_string()))?;
