            .get(iface, &req.property)
            .await
            .map_err(|e| Status::internal(e.to_string()))?;

        let json = serde_json::to_string(&val).map_err(|e| Status::internal(e.to_string()))?;

        Ok(Response::new(crate::proto::DbusGetPropertyResponse {
            success: true,
            json_value: json,
            error: String::new(),
        }))
    }

