        line_start: p["line_start"].as_i64().unwrap_or(0),
        line_end: p["line_end"].as_i64().unwrap_or(0),
        chunk_index: p["chunk_index"].as_i64().unwrap_or(0),
        total_chunks: p["total_chunks"].as_i64().unwrap_or(1),
