#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(tag = "type")]
enum BackendSpec {
    #[serde(rename = "ingress")]
    Ingress,
    #[serde(rename = "tcp")]
    Tcp { host: String, port: u16 },
    #[serde(rename = "grpc")]
